package io.translab.tantor.server.service;

import org.junit.jupiter.api.Test;
import java.time.Instant;
import java.util.*;
import static io.translab.tantor.server.service.KafkaExpansionWorkflow.*;
import static org.junit.jupiter.api.Assertions.*;

class KafkaExpansionWorkflowTest {
    final List<Participant> participants=List.of(new Participant("node1","controller.service",101,"controller"),new Participant("node2","broker.service",1,"broker"));
    @Test void dynamicControllerJoinsBeforeBrokerAndNeverTouchesExistingUnits(){var steps=compile(Mode.DYNAMIC,Layout.SEPARATE,participants);assertTrue(steps.stream().noneMatch(s->s.kind()==Kind.STOP || s.kind()==Kind.STAGE_VOTERS || s.kind()==Kind.APPLY_VOTERS));int verified=index(steps,Kind.VERIFY_CONTROLLER,"candidate:controller"),broker=index(steps,Kind.START,"candidate:broker");assertTrue(verified<broker);assertEquals(Kind.PUBLISH,steps.getLast().kind());}
    @Test void staticCombinedUnitsStopAndStartOnceWithExplicitCandidateBrokerDependency(){var both=new Participant("combined","kafka.service",1,"broker,controller");var steps=compile(Mode.STATIC,Layout.SEPARATE,List.of(both));assertEquals(1,steps.stream().filter(s->s.kind()==Kind.STOP).count());assertEquals(1,steps.stream().filter(s->s.kind()==Kind.START&&s.target().equals(both.key())).count());assertTrue(index(steps,Kind.VERIFY_CONTROLLER,"candidate:controller")<index(steps,Kind.START,"candidate:broker"));assertTrue(steps.stream().noneMatch(s->s.kind()==Kind.ADMIT));}
    @Test void sameUnitWithTwoDifferentIdsCannotEnterMaintenance(){assertThrows(IllegalArgumentException.class,()->compile(Mode.STATIC,Layout.CONTROLLER,List.of(new Participant("node1","kafka.service",1,"broker"),new Participant("node1","kafka.service",101,"controller"))));}
    @Test void uncertainControllerAdmissionCannotBeReplayedOrPublishHalfALayout(){var steps=compile(Mode.DYNAMIC,Layout.SEPARATE,participants);var c=new Checkpoints("a".repeat(64),steps,Map.of());while(c.next().orElseThrow().kind()!=Kind.ADMIT)complete(c);var admission=c.next().orElseThrow();c.intent(admission.id());assertTrue(c.reconciliationRequired());assertFalse(c.canCancelBeforeMutation());assertThrows(IllegalStateException.class,()->c.intent(admission.id()));var resumed=new Checkpoints("a".repeat(64),steps,c.snapshot());assertTrue(resumed.reconciliationRequired());assertEquals(admission,resumed.next().orElseThrow());assertTrue(resumed.reservationRequired());}
    @Test void controllerVerifiedBrokerFailureKeepsAllParentOwnership(){var steps=compile(Mode.DYNAMIC,Layout.SEPARATE,participants);var c=new Checkpoints("a".repeat(64),steps,Map.of());while(!(c.next().orElseThrow().kind()==Kind.START&&c.next().orElseThrow().target().equals("candidate:broker")))complete(c);var broker=c.next().orElseThrow();c.intent(broker.id());var resumed=new Checkpoints("a".repeat(64),steps,c.snapshot());assertEquals(broker,resumed.next().orElseThrow());assertTrue(resumed.reservationRequired());assertFalse(resumed.canCancelBeforeMutation());assertTrue(steps.stream().filter(s->s.kind()==Kind.VERIFY_CONTROLLER).allMatch(s->resumed.snapshot().get(s.id())==State.CONFIRMED));}
    @Test void staleForeignOrIncompleteEvidenceCannotAdvance(){var steps=compile(Mode.DYNAMIC,Layout.CONTROLLER,participants);var c=new Checkpoints("a".repeat(64),steps,Map.of());var step=c.next().orElseThrow();c.intent(step.id());for(var evidence:List.of(new Evidence("b".repeat(64),step.id(),step.target(),Instant.now(),step.kind().requiredFacts()),new Evidence("a".repeat(64),step.id(),step.target(),Instant.now().minusSeconds(120),step.kind().requiredFacts()),new Evidence("a".repeat(64),step.id(),step.target(),Instant.now(),Set.of())))assertThrows(IllegalStateException.class,()->c.confirm(evidence,Instant.now()));}
    @Test void terminalPublicationRequiresEveryPriorStageAndDrainedTasks(){var steps=compile(Mode.DYNAMIC,Layout.SEPARATE,participants);var c=new Checkpoints("a".repeat(64),steps,Map.of());while(c.next().orElseThrow().kind()!=Kind.PUBLISH)complete(c);assertTrue(c.reservationRequired());complete(c);assertFalse(c.reservationRequired());assertTrue(c.next().isEmpty());assertThrows(IllegalStateException.class,()->c.intent(steps.getFirst().id()));}
    @Test void corruptNonsequentialStoredCheckpointsAreRejected(){var steps=compile(Mode.STATIC,Layout.CONTROLLER,participants);assertThrows(IllegalArgumentException.class,()->new Checkpoints("a".repeat(64),steps,Map.of(steps.getLast().id(),State.CONFIRMED)));}
    int index(List<Step> steps,Kind kind,String target){for(int i=0;i<steps.size();i++)if(steps.get(i).kind()==kind&&steps.get(i).target().equals(target))return i;throw new AssertionError();}
    void complete(Checkpoints c){var step=c.next().orElseThrow();c.intent(step.id());c.confirm(new Evidence("a".repeat(64),step.id(),step.target(),Instant.now(),step.kind().requiredFacts()),Instant.now());}
}
